// === Tab: mySketch ===
/*
This is a #WCCChallenge for the theme "waves"!

This sketch has two components:

1. p5.strands waves. The ocean is just a plane, and its texture
   is created by moving around the normal per pixel with some noise.
2. A bloom effect. This is done by thresholding the base render to get
   just the white parts, blurring it, then adding it back on top of
	 the original with a blend mode.

I've added orbitControl(), try moving the scene around to see the reflections!
*/

let waves
let env

let base
let bloom

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)

	base = createFramebuffer({ antialias: false, depth: false })
	bloom = createFramebuffer({ antialias: false, depth: false })

	// Create the background gradient
	envBuf = createFramebuffer({ width: 400, height: 200 })
	envBuf.draw(() => {
		noStroke()
		beginShape(QUAD_STRIP)
		fill('#65B6FC')
		vertex(-envBuf.width/2, -envBuf.height/2)
		vertex(envBuf.width/2, -envBuf.height/2)
		fill('#CCE7FF')
		vertex(-envBuf.width/2, 1)
		vertex(envBuf.width/2, 1)
		vertex(-envBuf.width/2, envBuf.height/2)
		vertex(envBuf.width/2, envBuf.height/2)
		endShape()
	})
	env = envBuf.get()
	envBuf.remove()

	waves = baseMaterialShader().modify(() => {
		// Try adjusting this lower or higher to see how the reflections change!
		const bumpHeightScale = 40

		// A noise implementation. We're going to include something like this
		// in p5 in a future version.
		function mod289(x) {return x - floor(x * (1.0 / 289.0)) * 289.0;}
		function perm(x) {return mod289(((x * 34.0) + 1.0) * x);}
		function noise3(p){
				let a = floor(p);
				let d = p - a;
				d = d * d * (3.0 - 2.0 * d);

				let b = [a.x, a.x, a.y, a.y] + vec4(0.0, 1.0, 0.0, 1.0);
				let k1 = perm([b.x, b.y, b.x, b.y]);
				let k2 = perm([k1.x, k1.y, k1.x, k1.y] + [b.z, b.z, b.w, b.w]);

				let c = k2 + [a.z, a.z, a.z, a.z];
				let k3 = perm(c);
				let k4 = perm(c + 1.0);

				let o1 = fract(k3 * (1.0 / 41.0));
				let o2 = fract(k4 * (1.0 / 41.0));

				let o3 = o2 * d.z + o1 * (1.0 - d.z);
				let o4 = o3.yw * d.x + o3.xz * (1.0 - d.x);

				return smoothstep(0,1,o4.y * d.y + o4.x * (1.0 - d.y));
		}
		const fractalNoise3 = (v1, v2, t) => {
			const s = 0.35
			return noise3([v1, v2, t]) +
				s * noise3([v1 * 2, v2 * 2, t * 2]) +
				s*s * noise3([v1 * 4, v2 * 4, t * 4]) +
				s*s*s * noise3([v1 * 8, v2 * 8, t * 8]) +
				s*s*s*s * 0.5 * noise3([v1 * 16, v2 * 16, t * 16])
		}

		const t = uniformFloat(() => millis())
		getPixelInputs((inputs) => {
			// Find the position at the current pixel and scale it a bit
			// to make the noise look nice (also shifting it over time)
			const pos = inputs.texCoord * 150 + t * 0.0001

			// Function to get the height of the waves at the current position + time
			const bumpHeight = (x, y) => bumpHeightScale * fractalNoise3(x, y, t * 0.001)

			// Sample the height at the current position, and also a little down
			// and a little to the right. This gives us info to approximate the gradient
			// of the noise, and calculate a new normal.
			const h = bumpHeight(pos.x, pos.y)
			const hR = bumpHeight(pos.x + 0.01, pos.y)
			const hD = bumpHeight(pos.x, pos.y + 0.01)
			const norm = normalize(cross([1, hR - h, 0], [0, hD - h, 1]))

			// The normal doesn't yet take into account the orientation of
			// the scene. This maps it onto the orientation of the "real"
			// normal.
			const origNorm = inputs.normal
			const w = [1, 0, 0]
			const v = normalize(cross(w, origNorm))
			const u = normalize(cross(v, origNorm))
			let newNormal =
				u * norm.x +
				v * norm.z +
				origNorm * -norm.y

			inputs.normal = newNormal
			return inputs
		})
	})
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	// Draw the waves
	base.begin()
	orbitControl()
	panorama(env)
	directionalLight(100, 100, 100, 0, 1, 0.15)
	pointLight(255, 255, 255, 0, -height, -5000)
	ambientLight(150)

	push()
	emissiveMaterial(255)
	translate(0, -height, -5000)
	noStroke()
	sphere(150)
	pop()

	push()
	shader(waves)
	noStroke()
	fill('#4E668A')
	ambientMaterial('rgb(59,133,159)')
	specularMaterial(255)
	shininess(100)
	translate(0, width * 0.08)
	rotateX(PI/2)
	plane(width*16, width*16)
	pop()
	base.end()

	imageMode(CENTER)

	// Threshold + blur to get the bloom effect
	bloom.begin()
	image(base, 0, 0)
	filter(THRESHOLD, 0.9)
	filter(BLUR, 5)
	bloom.end()

	// Add everything back together
	image(base, 0, 0)
	push()
	blendMode(ADD)
	image(bloom, 0, 0)
	pop()
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
